source("h.R")
F <- function(h, base = NULL, x = NULL) { d <- html_parse(h, base_url = base); html_forms(if (is.null(x)) d else html_elements(d, x)) }
p("action base el", F("<base href='http://cdn/x/'><form></form><form action=''></form><form action='?q'></form><form action='#'></form>", "http://site/page?z#f")  |> lapply(`[[`, "action"))
p("action none", F("<form action=a></form><form></form>") |> lapply(`[[`, "action"))
p("method", sapply(F("<form method=POST><form></form></form><form method=' post'></form><form method=put></form><form method=DIALOG></form><form method=''></form>"), `[[`, "method"))
p("enctype", sapply(F("<form enctype='MULTIPART/form-data'></form><form enctype='text/plain'></form><form enctype=x></form>"), `[[`, "enctype"))
f <- F("<form id=f name=n><input><input type=TEXT name=a value=1><input type=checkbox name=c><input type=checkbox name=c value=2 checked><input type=radio name=r checked=false><input type=bogus name=b value=v><input type=hidden name=a value=dup><input type=file name=fi><input type=image name=im><input type=submit><input type=' text ' name=sp><button name=b1>B</button><button type=RESET value=rv></button><button type=menu></button><textarea name=t>\n line1\n</textarea><select name=s></select><select name=s1><option>a<option value=B disabled selected>b</select><select name=s2 multiple><option selected>a<option selected value=''>b</select><select name=s3><option disabled>a<optgroup disabled><option>g</optgroup><option label=L>  c  d </select><select name=s4><option selected>a<option selected>b</select><select name=s5><optgroup disabled><option>only</optgroup></select></form>")
print(f[[1]][1:5]); print(f[[1]]$fields[1:5]); print(f[[1]]$fields$options); str(f[[1]]$fields)
p("no controls", str(F("<form></form>")[[1]]$fields))
p("no forms", F("<p>")); p("nodeset no form", F("<form><p><input></form>", x = "p")); p("nodeset is form", length(F("<form><p><input></form>", x = "form, p")))
p("nested in nodeset", lapply(F("<div><form id=a><input name=x></form></div><form id=b><input name=y></form>", x = "div"), function(f) c(f$id, f$fields$name)))
p("form attr", lapply(F("<form id=a></form><form id=b><input name=in_b form=a><input name=nowhere form=zzz><input name=empty form=''><input name=tospan form=sp></form><span id=sp></span><div id=a2></div><input name=late form=a>"), function(f) c(f$id, f$fields$name)))
p("dup id", lapply(F("<div id=a></div><form id=a></form><input name=q form=a>"), function(f) c(f$id, f$fields$name)))
p("table form", lapply(F("<table><form id=f1><tr><td><input name=a></td></tr></form><tr><td><input name=b><form id=f2></form><input name=c></table><input name=out>"), function(f) c(f$id, f$fields$name)))
p("fieldset", F("<form><fieldset disabled><legend><input name=inlegend></legend><legend><input name=leg2></legend><input name=infs><fieldset><input name=nested></fieldset></fieldset><input name=free disabled=false></form>")[[1]]$fields[c("name","disabled")])
p("template controls", F("<form><template><input name=t></template><input name=v></form>")[[1]]$fields$name)
p("svg/foreign input", tr(F("<form><svg><input name=s></svg><math><button name=m></button></math><input name=h></form>")[[1]]$fields))
p("ref w specials", lapply(F("<form id='a]b'></form><form id='x y'></form><input form='a]b' name=q1><input form='x y' name=q2><form id='é'></form><input form='é' name=q3><input form=' x y' name=q4>"), function(f) c(f$id, f$fields$name)))
p("ref newline", F("<form id=a></form><input form='a&#10;b' name=q>"))
p("ref long", tr(length(F(paste0("<form id=a></form><input form='", strrep("z", 17000), "' name=q>")))))
p("ref NUL-ish ctrl", tr(length(F("<form id=a></form><input form='a&#1;b' name=q><input form='a&#9;' name=r><input form='a&#12;' name=s><input form='a&#13;' name=s>"))))
p("forms bad x", list(tr(html_forms(1)), tr(html_forms(NULL))))
d <- html_parse("<form id=a><input name=q></form>"); p("forms NA nodes", length(html_forms(html_elements(d, "form")[c(NA, 1, 1)])))
p("forms zero nodeset", html_forms(html_elements(d, "nope")))
